import sys
from asyncio import (AbstractEventLoop, CancelledError, Future, Protocol, Queue, Semaphore, Task, gather,
                     get_event_loop, sleep, transports)

__all__ = [
    'transports', 'gather', 'get_event_loop', 'Queue', 'Semaphore', 'AbstractEventLoop', 'Task', 'Protocol',
    'CancelledError', 'Future', 'sleep'
]

_python_version = sys.version_info[0], sys.version_info[1]

if _python_version < (3, 9):

    import asyncio
    import typing

    T = typing.TypeVar('T')

    class Queue(typing.Generic[T]):

        def __init__(self):
            self._target = asyncio.Queue()

        async def get(self) -> T:
            return await self._target.get()

        def put_nowait(self, item: T):
            self._target.put_nowait(item)
